  function isSeniorSource(source) {
    return /^s/i.test(String(source?.cardId || ""));
  }

  function createUnifiedPanelShell(source, panelRoot) {
    if (!panelRoot) return null;
    const existing = panelRoot.querySelector(":scope > .math-source-panel-scroll > .math-source-panel-content");
    if (existing) return existing;

    panelRoot.dataset.mathUnifiedPanel = "true";
    panelRoot.dataset.mathPanelLevel = isSeniorSource(source) ? "senior" : "junior";

    const scroll = document.createElement("div");
    scroll.className = "math-source-panel-scroll";

    const content = document.createElement("div");
    content.className = "math-source-panel-content";

    scroll.appendChild(content);
    panelRoot.appendChild(scroll);
    return content;
  }

  function getUnifiedPanelContent(panelRoot) {
    return panelRoot?.querySelector(":scope > .math-source-panel-scroll > .math-source-panel-content") || panelRoot;
  }

