  function getJmTopicM05HudFullscreenCss(source) {
    if (!['jm_topic_m05', 'jm_topic_m06', 'jm_topic_m07'].includes(String(source?.cardId || ''))) return '';
    const s = '.' + source.sceneClass;
    return `
/* JM_TOPIC_LINEAR_HUD_FULLSCREEN: All proof cards fit without an internal scrollbar. */
${s} #hud-panel.hud-panel,
${s} #hud-panel.hud-panel:not(.collapsed) {
  top: 12px !important;
  left: 12px !important;
  right: auto !important;
  bottom: auto !important;
  width: min(390px, calc(100% - 24px)) !important;
  max-width: min(390px, calc(100% - 24px)) !important;
  height: auto !important;
  max-height: none !important;
  overflow: visible !important;
  display: flex !important;
  flex-direction: column !important;
}
${s} #hud-panel.hud-panel.collapsed {
  width: min(220px, calc(100% - 24px)) !important;
  height: 42px !important;
  max-height: 42px !important;
  overflow: hidden !important;
}
${s} #hud-panel .hud-header {
  min-height: 42px !important;
  padding: 9px 12px !important;
}
${s} #hud-panel .hud-title {
  font-size: 12px !important;
  font-weight: 850 !important;
}
${s} #hud-panel .hud-content {
  flex: 0 0 auto !important;
  height: auto !important;
  max-height: none !important;
  overflow: visible !important;
  overflow-y: visible !important;
  scrollbar-width: none !important;
  padding: 8px 10px 10px !important;
  font-size: 11px !important;
  line-height: 1.34 !important;
}
${s} #hud-panel .hud-content::-webkit-scrollbar { display: none !important; }
${s} #hud-panel .proof-step-card,
${s} #hud-panel .hud-live-readout {
  margin: 5px 0 !important;
  padding: 8px 10px !important;
  border-radius: 6px !important;
  font-size: 11px !important;
  line-height: 1.34 !important;
}
${s} #hud-panel .proof-step-card b,
${s} #hud-panel .hud-live-readout b { font-size: 11px !important; }
${s} #hud-panel .proof-step-card:first-child,
${s} #hud-panel .hud-live-readout:first-child { margin-top: 0 !important; }
${s} #hud-panel .proof-step-card:last-child { margin-bottom: 0 !important; }
@media (max-width: 620px), (max-height: 620px) {
  ${s} #hud-panel.hud-panel,
  ${s} #hud-panel.hud-panel:not(.collapsed) { width: min(360px, calc(100% - 20px)) !important; max-width: min(360px, calc(100% - 20px)) !important; top: 10px !important; left: 10px !important; }
  ${s} #hud-panel .hud-content { padding: 7px 9px 8px !important; font-size: 10.5px !important; line-height: 1.28 !important; }
  ${s} #hud-panel .proof-step-card,
  ${s} #hud-panel .hud-live-readout { margin: 4px 0 !important; padding: 6px 8px !important; font-size: 10.5px !important; line-height: 1.28 !important; }
}
`;
  }

