  function setupEquationFlowTouchEnhancements(source, sceneRoot, cleanup) {
    if (source?.cardId !== "jm_topic_m04" || !sceneRoot) return;
    const svg = sceneRoot.querySelector("#geometry-svg");
    const layers = sceneRoot.querySelector("#draw-layer-elements");
    if (!svg) return;

    const syncDiagnosticLens = event => {
      if (event.pointerType !== "touch") return;
      const activeTab = sceneRoot.querySelector(".tab-btn.active")?.getAttribute("data-tab");
      if (activeTab !== "eq-errors") return;
      svg.dispatchEvent(new MouseEvent("mousemove", {
        bubbles: true,
        clientX: event.clientX,
        clientY: event.clientY
      }));
    };
    svg.addEventListener("pointermove", syncDiagnosticLens, { passive: true });
    cleanup.elementListeners.push([svg, "pointermove", syncDiagnosticLens, { passive: true }]);

    const labelInteractiveNodes = () => {
      if (!layers) return;
      layers.querySelectorAll(".eq-block, .eq-capsule-group, .error-step-group").forEach(node => {
        if (!node.hasAttribute("aria-label")) {
          node.setAttribute("role", "button");
          node.setAttribute("tabindex", "0");
          node.setAttribute("aria-label", "可操作的方程项");
        }
      });
    };
    labelInteractiveNodes();
    const observer = new MutationObserver(labelInteractiveNodes);
    if (layers) observer.observe(layers, { childList: true, subtree: true });
    cleanup.mutationObservers.push(observer);
  }

