    zoomTools.innerHTML = '<button type="button" data-zoom-out aria-label="\u7f29\u5c0f">-</button><button type="button" data-zoom-reset>\u8fd8\u539f</button><button type="button" data-zoom-in aria-label="\u653e\u5927">+</button><span data-zoom-value>100%</span>';
    sceneRoot.appendChild(zoomTools);

