      const viewWidth = width / sceneZoom;
      const viewHeight = height / sceneZoom;
      svg.setAttribute("viewBox", `${(width - viewWidth) / 2} ${(height - viewHeight) / 2} ${viewWidth} ${viewHeight}`);
      const value = zoomTools.querySelector("[data-zoom-value]");
