  async function ensureLocalDependencies(source) {
    if (!source.needsThree) return;
    if (!window.THREE) await loadScriptOnce(VENDOR_PATH + "three.min.js");
    if (!window.THREE || typeof window.THREE.OrbitControls !== "function") {
      await loadScriptOnce(VENDOR_PATH + "OrbitControls.js");
    }
    if (!window.THREE || typeof window.THREE.OrbitControls !== "function") {
      throw new Error("Local Three.js or OrbitControls is unavailable");
    }
  }

  function createMountState() {
    return {
      disposed: false,
      windowListeners: [],
      documentListeners: [],
      elementListeners: [],
      timeouts: new Set(),
      intervals: new Set(),
      rafIds: new Set(),
      mutationObservers: [],
      styleEl: null,
      sceneRoot: null,
      panelRoot: null
    };
  }

  function parseAdapterMeta(doc) {
    const metaNode = doc.querySelector('script[type="application/json"][data-math-source-adapter]');
    if (!metaNode) return {};
    const raw = metaNode.textContent || "{}";
    metaNode.remove();
    try {
      return JSON.parse(raw);
    } catch (error) {
      return {};
    }
  }

  function collectSourceStyle(doc) {
    const styles = [];
    doc.querySelectorAll("style").forEach(node => {
      styles.push(node.textContent || "");
      node.remove();
    });
    doc.querySelectorAll('link[rel="stylesheet"], link[as="style"]').forEach(node => node.remove());
    return styles.join("\n");
  }

  function collectSourceScript(doc) {
    const scripts = [];
    doc.querySelectorAll("script").forEach(node => {
      if (node.src) {
        node.remove();
        return;
      }
      const type = String(node.getAttribute("type") || "").trim().toLowerCase();
      if (type && type !== "text/javascript" && type !== "application/javascript") {
        node.remove();
        return;
      }
      scripts.push(node.textContent || "");
      node.remove();
    });
    return scripts.join("\n");
  }

  function normalizeLoadedSource(cardId, html, config, sourcePath, baseUrl) {
    const doc = new DOMParser().parseFromString(String(html || ""), "text/html");
    const fileMeta = parseAdapterMeta(doc);
    const configMeta = config && config.sourceAdapter && typeof config.sourceAdapter === "object" ? config.sourceAdapter : {};
    const meta = Object.assign({}, configMeta, fileMeta);
    const style = collectSourceStyle(doc);
    const script = collectSourceScript(doc);
    const body = doc.body ? doc.body.innerHTML : "";
    const safeCardId = cardId || meta.cardId || config?.cardId || "source-html-card";

    return {
      cardId: safeCardId,
      file: sourcePath || "source.html",
      panelSelector: meta.panelSelector || "#sidebar",
      needsThree: Boolean(meta.needsThree),
      stagePointerWindow: Boolean(meta.stagePointerWindow),
      bridgeTouchToMouse: meta.bridgeTouchToMouse !== false,
      sceneClass: meta.sceneClass || ("math-source-scene-" + safeCardId),
      panelClass: meta.panelClass || ("math-source-panel-" + safeCardId),
      stylePreScoped: meta.stylePreScoped !== false,
      baseUrl: baseUrl || window.location.href,
      inlineFunctionNames: Array.isArray(meta.inlineFunctionNames) ? meta.inlineFunctionNames : [],
      auxiliaryPanelSelectors: normalizeSelectorList(meta.auxiliaryPanelSelectors),
      body,
      style,
      script
    };
  }

  function loadTextViaXhr(url) {
    return new Promise((resolve, reject) => {
      if (typeof XMLHttpRequest !== "function") {
        reject(new Error("XMLHttpRequest is unavailable"));
        return;
      }
      const xhr = new XMLHttpRequest();
      xhr.open("GET", url, true);
      xhr.overrideMimeType?.("text/html; charset=utf-8");
      xhr.onreadystatechange = () => {
        if (xhr.readyState !== 4) return;
        if (xhr.status >= 200 && xhr.status < 300) resolve(xhr.responseText || "");
        else reject(new Error("XHR failed: " + xhr.status));
      };
      xhr.onerror = () => reject(new Error("XHR network error"));
      xhr.send();
    });
  }

  function loadTextViaIframe(url) {
    return new Promise((resolve, reject) => {
      const iframe = document.createElement("iframe");
      let done = false;
      const finish = (error, text) => {
        if (done) return;
        done = true;
        window.clearTimeout(timer);
        iframe.onload = null;
        iframe.onerror = null;
        iframe.remove();
        if (error) reject(error);
        else resolve(text || "");
      };
      const timer = window.setTimeout(() => finish(new Error("iframe source timeout")), 8000);
      iframe.setAttribute("sandbox", "allow-same-origin");
      iframe.style.cssText = "position:absolute;width:0;height:0;border:0;opacity:0;pointer-events:none;left:-9999px;top:-9999px;";
      iframe.onload = () => {
        try {
          const doc = iframe.contentDocument;
          const html = doc?.documentElement?.outerHTML || "";
          finish(null, html ? "<!DOCTYPE html>\n" + html : "");
        } catch (error) {
          finish(error);
        }
      };
      iframe.onerror = () => finish(new Error("iframe source load error"));
      document.body.appendChild(iframe);
      iframe.src = url;
    });
  }

  async function loadTextResource(url) {
    if (typeof fetch === "function") {
      try {
        const response = await fetch(url, { cache: "no-store" });
        if (response.ok) return await response.text();
      } catch (error) {}
    }
    try {
      return await loadTextViaXhr(url);
    } catch (error) {}
    return loadTextViaIframe(url);
  }

  function inferBookFolderFromCardId(cardId) {
    const id = String(cardId || "");
    const senior = id.match(/^s([bx])(\d)_/);
    if (senior) return "s_" + senior[1] + senior[2];
    const junior = id.match(/^(j\d[ab])_/);
    if (junior) return junior[1];
    return id.slice(0, 3);
  }

  function getSourceFolderCandidates(cardId, context) {
    const config = context?.config || {};
    const entry = context?.sceneEntry || {};
    const id = String(cardId || config.cardId || "");
    const inferredBook = inferBookFolderFromCardId(id);
    const candidates = [
      entry.folder,
      context?.folder,
      config.folder,
      config.sourceAdapter?.folder,
      inferredBook ? "visualizations/books/" + inferredBook + "/" + id : "",
      id ? "visualizations/books/" + id.slice(0, 3) + "/" + id : ""
    ];
    return Array.from(new Set(candidates.map(item => String(item || "").trim()).filter(Boolean)));
  }

  function localizeCardSource(source) {
    if (!source || source.cardId !== "j7b_m04") return source;
    return {
      ...source,
      body: String(source.body || "")
        .replace("角关系引擎 <span style=\"font-size:0.8rem;color:var(--accent-pink)\">Super</span>", "角关系扫描器 <span style=\"font-size:0.8rem;color:var(--accent-pink)\">进阶版</span>")
        .replace("标准井字 (4线)", "标准井字（四线）")
        .replace("A字型 (截断三角形)", "三角截线型")
        .replace("Z字折线型", "折线截线型")
        .replace("⏸ 强制 L1 // L2", "⏸ 强制两线平行")
        .replace(/>OFF</g, ">关闭<")
        .replace("● RELATION SCANNER ●", "● 角关系扫描器 ●")
        .replace(">VS<", ">对比<"),
      script: String(source.script || "")
        .replace(
          "                { p1: {x: 100, y: -250}, p2: {x: -100, y: 300} },\n                { p1: {x: -2000, y: 2000}, p2: {x: -1900, y: 2000} } // L4 offscreen",
          "                { p1: {x: 100, y: -250}, p2: {x: -100, y: 300} },\n                { p1: {x: -25, y: -250}, p2: {x: -225, y: 300} } // L4: visible parallel guide"
        )
        .replace(
          "        function selectAngle(ang) {",
          `        function isAngleVisible(ang) {
            const marker = ang?.els?.text;
            const canvas = dom.svg.getBoundingClientRect();
            const rect = marker?.getBoundingClientRect?.();
            const margin = 8;
            return Boolean(rect && canvas &&
                rect.left >= canvas.left + margin && rect.right <= canvas.right - margin &&
                rect.top >= canvas.top + margin && rect.bottom <= canvas.bottom - margin);
        }

        function selectAngle(ang) {`
        )
        .replace(
          "                    if (a === ang) return;\n                    const res = analyzeRelationship(ang, a);",
          "                    if (a === ang || !isAngleVisible(a)) return;\n                    const res = analyzeRelationship(ang, a);"
        )
        .replace(/'ON'/g, "'开启'")
        .replace(/'OFF'/g, "'关闭'")
    };
  }

  async function resolveCardSource(cardId, context) {
    const config = context?.config || {};
    const sourcePath = config.source || config.sourceHtml || "source.html";
    const hasExternalSource = Boolean(config.source || config.sourceHtml || config.sourceAdapter);
    if (!hasExternalSource && LEGACY_SOURCES[cardId]) return localizeCardSource(LEGACY_SOURCES[cardId]);

    const folders = getSourceFolderCandidates(cardId, context);
    let lastUrl = "";
    for (const folder of folders) {
      const cleanFolder = folder.replace(/\/+$/, "");
      const url = appendRuntimeVersion(cleanFolder + "/" + sourcePath.replace(/^\/+/, ""));
      const baseUrl = new URL(cleanFolder + "/", window.location.href).href;
      lastUrl = url;
      try {
        const html = await loadTextResource(url);
        if (html) return normalizeLoadedSource(cardId, html, config, sourcePath, baseUrl);
      } catch (error) {}
    }
    if (LEGACY_SOURCES[cardId]) return localizeCardSource(LEGACY_SOURCES[cardId]);
    throw new Error("Failed to load local card source: " + (lastUrl || sourcePath));
  }

  function cleanupMount(state) {
    if (!state || state.disposed) return;
    state.disposed = true;
    state.windowListeners.forEach(([target, type, handler, options]) => target.removeEventListener(type, handler, options));
    state.documentListeners.forEach(([type, handler, options]) => document.removeEventListener(type, handler, options));
    state.elementListeners.forEach(([target, type, handler, options]) => target.removeEventListener(type, handler, options));
    state.timeouts.forEach(id => window.clearTimeout(id));
    state.intervals.forEach(id => window.clearInterval(id));
    state.rafIds.forEach(id => window.cancelAnimationFrame(id));
    state.mutationObservers.forEach(observer => observer.disconnect());
    state.styleEl?.remove();
    state.sceneRoot?.remove();
    state.panelRoot?.remove();
  }

