  function setupJ9bM11KnowledgeHud(source, sceneRoot, cleanup) {
    if (!sceneRoot || !['j9b_m06', 'j9b_m08', 'j9b_m10', 'j9b_m11'].includes(source?.cardId)) return;
    const hud = sceneRoot.querySelector('#route-knowledge-hud');
    const header = hud?.querySelector('.route-knowledge-header');
    const stage = sceneRoot.querySelector('.simulation-container, .canvas-section');
    const titleWrap = hud?.querySelector('.route-knowledge-title-wrap');
    const logo = hud?.querySelector('.route-knowledge-logo');
    const arrow = hud?.querySelector('.route-knowledge-arrow');
    const arrowIcon = arrow?.querySelector('svg');
    const body = hud?.querySelector('.route-knowledge-body');
    const rows = hud?.querySelectorAll('.route-knowledge-row') || [];
    const labels = hud?.querySelectorAll('.route-knowledge-label') || [];
    const texts = hud?.querySelectorAll('.route-knowledge-text') || [];
    const conclusion = hud?.querySelector('.route-knowledge-conclusion');
    const conclusionLabel = conclusion?.querySelector('span');
    const conclusionFormula = conclusion?.querySelector('strong');
    if (!hud || !header) return;

    const set = (node, property, value) => {
      if (!node) return;
      if (value == null) node.style.removeProperty(property);
      else node.style.setProperty(property, value, 'important');
    };
    const applyResponsiveLayout = () => {
      const rect = stage?.getBoundingClientRect();
      const width = rect?.width || 0;
      const height = rect?.height || 0;
      const compact = width > 0 && (width <= 480 || height <= 480);
      const tiny = compact && (width <= 330 || height <= 380);

      if (!compact) {
        [
          [hud, 'width'], [hud, 'top'], [hud, 'left'],
          [header, 'min-height'], [header, 'padding'], [header, 'font-size'],
          [titleWrap, 'gap'], [logo, 'width'], [logo, 'height'], [logo, 'flex-basis'],
          [arrow, 'width'], [arrow, 'height'], [arrow, 'flex-basis'],
          [arrowIcon, 'width'], [arrowIcon, 'height'], [body, 'max-height'], [body, 'padding'], [body, 'overflow-y'],
          [conclusion, 'gap'], [conclusion, 'margin-top'], [conclusion, 'padding'],
          [conclusionLabel, 'font-size'], [conclusionFormula, 'font-size']
        ].forEach(([node, property]) => set(node, property, null));
        rows.forEach(node => set(node, 'padding', null));
        labels.forEach(node => { set(node, 'margin-bottom', null); set(node, 'font-size', null); });
        texts.forEach(node => { set(node, 'font-size', null); set(node, 'line-height', null); });
        return;
      }

      const hudWidth = Math.min(tiny ? 220 : 254, Math.max(156, width - (tiny ? 16 : 20)));
      const bodyMaxHeight = Math.max(88, Math.min(tiny ? 142 : 180, height * (tiny ? 0.48 : 0.42) - (tiny ? 36 : 42)));
      set(hud, 'width', `${hudWidth}px`);
      set(hud, 'top', tiny ? '8px' : '10px');
      set(hud, 'left', tiny ? '8px' : '10px');
      set(header, 'min-height', tiny ? '36px' : '40px');
      set(header, 'padding', tiny ? '4px 7px 4px 10px' : '5px 8px 5px 12px');
      set(header, 'font-size', tiny ? '11px' : '12px');
      set(titleWrap, 'gap', tiny ? '7px' : '8px');
      set(logo, 'width', tiny ? '14px' : '15px');
      set(logo, 'height', tiny ? '14px' : '15px');
      set(logo, 'flex-basis', tiny ? '14px' : '15px');
      set(arrow, 'width', tiny ? '23px' : '26px');
      set(arrow, 'height', tiny ? '23px' : '26px');
      set(arrow, 'flex-basis', tiny ? '23px' : '26px');
      set(arrowIcon, 'width', tiny ? '14px' : '15px');
      set(arrowIcon, 'height', tiny ? '14px' : '15px');
      set(body, 'max-height', `${bodyMaxHeight}px`);
      set(body, 'padding', tiny ? '0 8px 8px' : '0 10px 9px');
      set(body, 'overflow-y', 'auto');
      rows.forEach(node => set(node, 'padding', tiny ? '6px 0' : '7px 0'));
      labels.forEach(node => { set(node, 'margin-bottom', '2px'); set(node, 'font-size', tiny ? '0.62rem' : '0.66rem'); });
      texts.forEach(node => { set(node, 'font-size', tiny ? '0.70rem' : '0.75rem'); set(node, 'line-height', '1.42'); });
      set(conclusion, 'gap', tiny ? '5px' : '6px');
      set(conclusion, 'margin-top', tiny ? '6px' : '7px');
      set(conclusion, 'padding', tiny ? '6px 7px' : '7px 8px');
      set(conclusionLabel, 'font-size', tiny ? '0.62rem' : '0.66rem');
      set(conclusionFormula, 'font-size', tiny ? '0.74rem' : '0.78rem');
    };

    const toggle = event => {
      event.preventDefault();
      event.stopPropagation();
      const expanded = hud.classList.toggle('expanded');
      hud.classList.toggle('collapsed', !expanded);
      header.setAttribute('aria-expanded', String(expanded));
    };
    header.addEventListener('click', toggle);
    cleanup.elementListeners.push([header, 'click', toggle, false]);
    applyResponsiveLayout();
    if (stage && typeof ResizeObserver === 'function') {
      const observer = new ResizeObserver(applyResponsiveLayout);
      observer.observe(stage);
      cleanup.mutationObservers.push(observer);
    }
  }

